      "path": "packages/baro-dsh/src/adapters/dsh/subprocess-runner.ts",
      "content": "import { createInterface } from 'node:readline'\nimport type { SubprocessHandle, SubprocessSpawnSpec } from '@deepseek-ai/dsh-subprocess'\nimport type { RunProcess, RunProcessPort, RunRequest } from '../../application/delegate-run.js'\n\n/* Runs `baro <goal> --headless` through dsh's subprocess service. The parent\n   env is scrubbed by dsh; credentials reach the child only through `env`. */\n\nexport interface BaroCommand {\n  readonly command: string\n  readonly args: readonly string[]\n  readonly localOnly: boolean\n  readonly env: Readonly<Record<string, string>>\n  readonly disposeGraceMs: number\n}\n\nexport class SubprocessRunner implements RunProcessPort {\n  constructor(\n    private readonly spawn: (spec: SubprocessSpawnSpec) => SubprocessHandle,\n    private readonly baro: BaroCommand,\n  ) {}\n\n  start(request: RunRequest): RunProcess {\n    const argv = [\n      this.baro.command,\n      request.goal,\n      '--headless',\n      '--cwd',\n      request.cwd,\n      ...(this.baro.localOnly ? ['--local-only'] : []),\n      ...this.baro.args,\n    ]\n    // stdin must be closed, not merely silent: headless baro answers its own\n    // intake questions only once stdin hits EOF, and blocks on an open pipe.\n    const child = this.spawn({\n      argv,\n      cwd: request.cwd,\n      stdio: { stdin: 'ignore', stdout: 'pipe', stderr: 'inherit' },\n      graceMs: this.baro.disposeGraceMs,\n      signal: request.signal,\n      env: { ...this.baro.env, BARO_RUN_ID: request.runId },\n    })\n    return {\n      lines: lines(child.stdout),\n      exited: child.done.then(outcome => ({ exitCode: outcome.exitCode })),\n      terminate: () => child.terminate(),\n      waitForExit: () => child.waitForExit(),\n    }\n  }\n}\n\nasync function* lines(stream: NodeJS.ReadableStream | undefined): AsyncIterable<string> {\n  if (!stream) return\n  yield* createInterface({ input: stream, crlfDelay: Number.POSITIVE_INFINITY })\n}\n"
    },
    {
      "path": "packages/baro-dsh/src/index.ts",
      "content": "import type { Context } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-settings'\nimport z from '@deepseek-ai/schemastery'\nimport { JobsObserver } from './adapters/dsh/jobs-observer.js'\nimport { SettingsObserver, type RunRecord, type RunsDocument } from './adapters/dsh/settings-observer.js'\nimport { BaroSubagentProvider } from './adapters/dsh/subagent-provider.js'\nimport { SubprocessRunner } from './adapters/dsh/subprocess-runner.js'\nimport { DelegateRun, composeObservers } from './application/delegate-run.js'\n\nexport { DelegateRun, composeObservers } from './application/delegate-run.js'\nexport type { RunObserverPort, RunProcessPort, RunRequest, RunSubscription, RunView } from './application/delegate-run.js'\nexport { MILESTONE_TYPES, isMilestone, parseLine } from './domain/protocol.js'\nexport { RunTracker, classifyDone, resolveTerminal } from './domain/run.js'\nexport type { RunRecord, RunsDocument } from './adapters/dsh/settings-observer.js'\n\n/* Composition root: the dsh plugin wires dsh's services into the ports and\n   registers the provider. Everything else in this package is dsh-free. */\n\nexport const name = 'baro-dsh'\n// cordis has no optional injection; all five are in dsh-base.\nexport const inject = ['subagents', 'subprocess', 'jobs', 'settings', 'systemPrompt']\n\n/* dsh's delegation tool carries a fixed description, so the one place to tell\n   the model what baro is for is a prompt section. It is a run, not a helper:\n   minutes of planning and verification that only pay off past one small edit. */\nexport const DELEGATION_GUIDANCE = `\\\nThe \"baro\" tool delegates a goal to baro, an autonomous run that plans the goal into stories, executes them in parallel with coding agents, reviews each story independently, and verifies the merged result. A run takes 10–30 minutes and returns a certified outcome, not a chat reply.\nUse \"baro\" for goals that span several files or need more than one coherent change, where a plan, parallel execution and independent verification are worth the wait. For a single small edit, a question, or an investigation, do the work yourself or use the ordinary subagent. Give baro the full goal in one prompt; it does not see this conversation.`\n\n/** Namespace the browser panel reads; must match `src/client`. */\nexport const RUNS_SETTINGS_NS = 'baro-dsh'\n\nexport interface Config {\n  providerName?: string\n  command?: string\n  args?: string[]\n  localOnly?: boolean\n  cwd?: string\n  env?: Record<string, string>\n  disposeGraceMs?: number\n}\n\nexport const Config: z<Config> = z.object({\n  providerName: z.string().min(1).default('baro'),\n  command: z.string().min(1).default('baro'),\n  args: z.array(z.string()).default([]),\n  localOnly: z.boolean().default(true),\n  cwd: z.string(),\n  env: z.dict(z.string()).default({}),\n  disposeGraceMs: z.number().default(5_000),\n})\n\nconst RunsSchema: z<RunsDocument> = z.object({\n  runs: z.dict(z.any()).default({}),\n}) as unknown as z<RunsDocument>\n\nexport function apply(ctx: Context, config: Config): void {\n  const resolved = Config(config)\n  const warn = (what: string) => (error: unknown) => {\n    console.error(`[baro-dsh] ${what}: ${error instanceof Error ? error.message : String(error)}`)\n  }\n\n  const runner = new SubprocessRunner(spec => ctx.subprocess.spawn(spec), {\n    command: resolved.command ?? 'baro',\n    args: resolved.args ?? [],\n    localOnly: resolved.localOnly ?? true,\n    env: resolved.env ?? {},\n    disposeGraceMs: resolved.disposeGraceMs ?? 5_000,\n  })\n\n  // The registry refuses a job no controller serves. Our runs are unowned, so\n  // this plugin attaches its own controller for the scope it lives in instead\n  // of depending on which agent preset happened to load dsh-tool-jobs.\n  ctx.effect(() => ctx.jobs.attachController('baro-dsh'))\n\n  const runs = ctx.settings.register(RUNS_SETTINGS_NS, RunsSchema, { base: { runs: {} } })\n  const settingsObserver = new SettingsObserver(\n    {\n      get: () => runs.get(),\n      update: patch => runs.update(patch as { runs: Record<string, RunRecord> }),\n    },\n    warn('run panel state not persisted'),\n  )\n\n  const provider = new BaroSubagentProvider(\n    resolved.providerName ?? 'baro',\n    new DelegateRun(\n      runner,\n      composeObservers([new JobsObserver(ctx.jobs), settingsObserver], warn('run observer failed')),\n      warn('run continues without an observer'),\n    ),\n    resolved.cwd,\n  )\n  ctx.effect(() => ctx.subagents.registerProvider(provider))\n  ctx.effect(() =>\n    ctx.systemPrompt.section({\n      name: 'baro:delegation',\n      order: 400,\n      text: DELEGATION_GUIDANCE.replaceAll('\"baro\"', `\"${resolved.providerName ?? 'baro'}\"`),\n    }),\n  )\n}\n"
    },
    {
      "path": "packages/baro-dsh/src/adapters/dsh/subagent-provider.ts",
      "content": "import { randomUUID } from 'node:crypto'\nimport { brandString } from '@deepseek-ai/dsh-brand'\nimport type { ContentBlock } from '@deepseek-ai/dsh-llm'\nimport type { SessionId } from '@deepseek-ai/dsh-session'\nimport {\n  NO_START_CAPABILITIES,\n  resolveChildCwd,\n  type ResolvedSubagentStartRequest,\n  type SubagentCapabilities,\n  type SubagentProvider,\n  type SubagentResult,\n  type SubagentRun,\n  type SubagentStopReason,\n} from '@deepseek-ai/dsh-subagent'\nimport type { DelegateRun, DelegationOutcome } from '../../application/delegate-run.js'\n\n/* dsh's remote, fire-and-return provider seam over the delegation use case.\n   Nothing of the live feed reaches the model; the job is where a human\n   watches, the result is what the model reads. */\n\nconst DIAGNOSTIC_LIMIT = 4000\n\nexport class BaroSubagentProvider implements SubagentProvider {\n  readonly capabilities: SubagentCapabilities = NO_START_CAPABILITIES\n  readonly inheritsParentContext = false\n\n  constructor(\n    readonly name: string,\n    private readonly delegate: DelegateRun,\n    private readonly configuredCwd: string | undefined,\n  ) {}\n\n  async start(request: ResolvedSubagentStartRequest): Promise<SubagentRun> {\n    const goal = promptText(request.prompt)\n    const cwd = resolveChildCwd(this.name, this.configuredCwd, request.parent.session.header.cwd)\n    const id = brandString<SessionId>(randomUUID())\n    const delegation = this.delegate.start({\n      goal,\n      cwd,\n      label: request.label ?? truncate(goal, 80),\n      runId: id,\n      signal: request.signal,\n    })\n    return {\n      id,\n      localAgent: undefined,\n      result: delegation.outcome.then(toResult),\n      dispose: () => delegation.dispose(),\n    }\n  }\n}\n\nfunction toResult(outcome: DelegationOutcome): SubagentResult {\n  const stopReason: SubagentStopReason = outcome.terminal\n  const done = outcome.summary.done\n  return {\n    output: [{ type: 'text', text: outcome.text } satisfies ContentBlock],\n    structured: done\n      ? {\n          success: done.success === true,\n          abortCode: typeof done.abort_code === 'string' ? done.abort_code : null,\n          prUrl: outcome.summary.prUrl ?? null,\n        }\n      : undefined,\n    diagnostic: stopReason === 'completed' ? undefined : truncate(outcome.text, DIAGNOSTIC_LIMIT),\n    stopReason,\n  }\n}\n\nfunction promptText(blocks: readonly ContentBlock[]): string {\n  return blocks\n    .map(block => (block.type === 'text' ? block.text : ''))\n    .filter(Boolean)\n    .join('\\n')\n    .trim()\n}\n\nfunction truncate(text: string, max: number): string {\n  return text.length <= max ? text : `${text.slice(0, max - 1)}…`\n}\n"
    },
    {
      "path": "packages/baro-dsh/src/application/delegate-run.ts",
      "content": "import { parseLine } from '../domain/protocol.js'\nimport { RunTracker, type RunSummary, type Terminal, renderOutcome, renderProgress, resolveTerminal } from '../domain/run.js'\n\n/* The one use case: hand baro a goal, follow the run, report how it ended.\n   Host-agnostic by construction — the ports below are the only way in or\n   out, so the same use case serves dsh today and any other harness later. */\n\nexport interface RunRequest {\n  readonly goal: string\n  readonly cwd: string\n  readonly label: string\n  readonly runId: string\n  readonly signal: AbortSignal\n}\n\nexport interface RunProcess {\n  /** stdout, one protocol line per element. */\n  readonly lines: AsyncIterable<string>\n  readonly exited: Promise<{ exitCode: number | null }>\n  terminate(): void\n  waitForExit(): Promise<unknown>\n}\n\nexport interface RunProcessPort {\n  start(request: RunRequest): RunProcess\n}\n\nexport interface RunView {\n  readonly id: string\n  readonly label: string\n  readonly startedAt: string\n  summary(): RunSummary\n  progress(): string\n  cancel(reason?: string): void\n}\n\nexport interface RunSubscription {\n  /** A milestone landed; the view's summary moved. */\n  changed?(): void\n  closed(terminal: Terminal): void\n}\n\n/** Where a human watches a run. Optional, and never load-bearing: a run without an observer still completes. */\nexport interface RunObserverPort {\n  opened(view: RunView): RunSubscription\n}\n\nexport interface DelegationOutcome {\n  readonly terminal: Terminal\n  readonly text: string\n  readonly summary: RunSummary\n}\n\nexport interface Delegation {\n  readonly outcome: Promise<DelegationOutcome>\n  cancel(reason?: string): void\n  dispose(): Promise<void>\n}\n\n/* Several observers, each isolated: a panel that throws must not take the\n   jobs entry down with it, nor the run. */\nexport function composeObservers(\n  observers: readonly RunObserverPort[],\n  onFailure?: (error: unknown) => void,\n): RunObserverPort {\n  return {\n    opened(view) {\n      const subscriptions: RunSubscription[] = []\n      for (const observer of observers) {\n        try {\n          subscriptions.push(observer.opened(view))\n        } catch (error) {\n          onFailure?.(error)\n        }\n      }\n      const guarded = (fn: () => void) => {\n        try {\n          fn()\n        } catch (error) {\n          onFailure?.(error)\n        }\n      }\n      return {\n        changed: () => {\n          for (const s of subscriptions) if (s.changed) guarded(() => s.changed?.())\n        },\n        closed: terminal => {\n          for (const s of subscriptions) guarded(() => s.closed(terminal))\n        },\n      }\n    },\n  }\n}\n\nexport class DelegateRun {\n  constructor(\n    private readonly process: RunProcessPort,\n    private readonly observer: RunObserverPort | undefined,\n    private readonly onObserverFailure?: (error: unknown) => void,\n  ) {}\n\n  start(request: RunRequest): Delegation {\n    if (!request.goal.trim()) throw new Error('baro needs a goal — the delegation prompt is empty')\n    const tracker = new RunTracker()\n\n    let child: RunProcess | undefined\n    let aborted = false\n    const cancel = (reason?: string) => {\n      aborted = true\n      child?.terminate()\n      void reason\n    }\n    // The observer opens before the process starts, and its failure is not the\n    // run's failure: a panel that cannot be shown must never orphan a child or\n    // turn a deliverable delegation into an error.\n    let subscription: RunSubscription | undefined\n    try {\n      subscription = this.observer?.opened({\n        id: request.runId,\n        label: request.label,\n        startedAt: new Date().toISOString(),\n        summary: () => tracker.summary(),\n        progress: () => renderProgress(tracker.summary()),\n        cancel,\n      })\n    } catch (error) {\n      this.onObserverFailure?.(error)\n    }\n    const notify = (fn: (() => void) | undefined) => {\n      try {\n        fn?.()\n      } catch (error) {\n        this.onObserverFailure?.(error)\n      }\n    }\n\n    child = this.process.start(request)\n    const started = child\n    const followed = (async () => {\n      for await (const line of started.lines) {\n        const event = parseLine(line)\n        if (!event) continue\n        const before = tracker.summary().revision\n        tracker.accept(event)\n        if (tracker.summary().revision !== before) notify(subscription?.changed?.bind(subscription))\n      }\n    })()\n\n    const outcome = (async (): Promise<DelegationOutcome> => {\n      const { exitCode } = await started.exited\n      await followed.catch(() => undefined)\n      const summary = tracker.summary()\n      const terminal = resolveTerminal(aborted || request.signal.aborted, exitCode, summary.done)\n      notify(subscription ? () => subscription?.closed(terminal) : undefined)\n      return { terminal, text: renderOutcome(summary, terminal), summary }\n    })()\n\n    return {\n      outcome,\n      cancel,\n      dispose: async () => {\n        cancel('disposed')\n        await started.waitForExit()\n      },\n    }\n  }\n}\n"
    },
    {
      "path": "packages/baro-dsh/src/adapters/dsh/jobs-observer.ts",
      "content": "import type { JobHooks, JobOutcome, JobRegistry } from '@deepseek-ai/dsh-jobs'\nimport type { RunObserverPort, RunSubscription, RunView } from '../../application/delegate-run.js'\nimport type { Terminal } from '../../domain/run.js'\n\n/* Every run is one unowned `baro-N` job: unowned so the whole frame sees it\n   in dsh's own jobs UI, not only the delegating agent. */\n\ndeclare module '@deepseek-ai/dsh-jobs' {\n  interface JobKindMap {\n    baro: 'baro'\n  }\n}\n\nexport class JobsObserver implements RunObserverPort {\n  constructor(private readonly jobs: JobRegistry) {}\n\n  opened(view: RunView): RunSubscription {\n    let settle: ((outcome: JobOutcome) => void) | undefined\n    const done = new Promise<JobOutcome>(resolve => {\n      settle = resolve\n    })\n    const hooks: JobHooks = {\n      cancel: reason => view.cancel(reason),\n      done,\n      readOutput: () => view.progress(),\n    }\n    this.jobs.start({ kind: 'baro', label: view.label, run: () => hooks })\n    let settled = false\n    return {\n      closed: terminal => {\n        if (settled) return\n        settled = true\n        settle?.(toJobOutcome(terminal))\n      },\n    }\n  }\n}\n\nfunction toJobOutcome(terminal: Terminal): JobOutcome {\n  switch (terminal) {\n    case 'completed':\n      return { status: 'completed' }\n    case 'aborted':\n      return { status: 'killed', detail: 'cancelled' }\n    default:\n      return { status: 'failed', detail: terminal }\n  }\n}\n"
    },
    {
      "path": "packages/baro-dsh/src/domain/run.ts",
      "content": "import { type BaroEvent, describe, isMilestone, numberField, stringField } from './protocol.js'\n\n/* The run as the delegation sees it: a bounded fold of the stream into the\n   facts a result or a panel needs. Bounded on purpose — a long run emits\n   thousands of activity lines, and a result diagnostic has a 4 KiB ceiling. */\n\n/** How a run ended, in a vocabulary a host can map onto its own. */\nexport type Terminal = 'completed' | 'error' | 'max-tokens' | 'aborted'\n\n/* `done.abort_code` is a classification only when every failed story agreed\n   on one code; a prose-only abort is `error`, never guessed further — with one\n   exception. baro marks a run unsuccessful when its goal contract keeps open\n   invariants even though every story merged and verification passed. For the\n   delegating agent that run delivered; calling it an error made the parent\n   conclude nothing was produced. It is `completed`, and the text carries the\n   open contract. */\nexport function classifyDone(done: BaroEvent): Terminal {\n  if (done.success === true) return 'completed'\n  if (done.abort_code === 'token_ceiling') return 'max-tokens'\n  return deliveredDespiteContract(done) ? 'completed' : 'error'\n}\n\nexport function deliveredDespiteContract(done: BaroEvent): boolean {\n  if (done.success === true || done.abort_code !== undefined) return false\n  const stats = done.stats as Record<string, unknown> | undefined\n  const completed = typeof stats?.stories_completed === 'number' ? stats.stories_completed : 0\n  const skipped = typeof stats?.stories_skipped === 'number' ? stats.stories_skipped : 0\n  return completed > 0 && skipped === 0 && done.verification_status === 'passed'\n}\n\nexport function resolveTerminal(aborted: boolean, exitCode: number | null, done: BaroEvent | undefined): Terminal {\n  if (aborted) return 'aborted'\n  if (done) return classifyDone(done)\n  // No `done` line: the process died before baro could classify anything.\n  return exitCode === 0 ? 'completed' : 'error'\n}\n\n/* Where the run is. `init` is the first milestone but arrives minutes in —\n   intake is silent on the stream, the architect and planner announce\n   themselves with non-milestone events — so a watcher needs the phase, not\n   only the certified outcomes. */\nexport type Phase = 'intake' | 'architect' | 'planning' | 'executing' | 'finalizing' | 'done'\n\nexport interface RunSummary {\n  readonly protocol: number | undefined\n  readonly project: string | undefined\n  readonly phase: Phase\n  /** Last live-feed line worth a glance (activity, story log), never archived. */\n  readonly activity: string | undefined\n  readonly storiesTotal: number\n  readonly completed: number\n  readonly total: number\n  readonly prUrl: string | undefined\n  readonly done: BaroEvent | undefined\n  /** Milestone lines in arrival order, oldest dropped past the limit. */\n  readonly milestones: readonly string[]\n  /** Bumps whenever anything above moved; cheap change detection for observers. */\n  readonly revision: number\n}\n\nconst ACTIVITY_LIMIT = 140\n\nexport class RunTracker {\n  private protocol: number | undefined\n  private project: string | undefined\n  private phase: Phase = 'intake'\n  private activity: string | undefined\n  private storiesTotal = 0\n  private completed = 0\n  private total = 0\n  private prUrl: string | undefined\n  private done: BaroEvent | undefined\n  private readonly milestones: string[] = []\n  private revision = 0\n\n  constructor(private readonly limit = 200) {}\n\n  accept(event: BaroEvent): void {\n    const before = this.revision\n    switch (event.type) {\n      case 'architect_start':\n        this.setPhase('architect')\n        this.setActivity('architect is examining the repository')\n        break\n      case 'architect_complete':\n      case 'architect_skipped':\n      case 'planning_open':\n        this.setPhase('planning')\n        this.setActivity('planner is composing the stories')\n        break\n      case 'plan_fragment': {\n        this.setPhase('planning')\n        const stories = Array.isArray(event.stories) ? event.stories : []\n        this.storiesTotal += stories.length\n        const titles = stories.map(s => (typeof s === 'object' && s !== null ? stringField(s as BaroEvent, 'title', 'id') : undefined)).filter(Boolean)\n        if (titles.length) this.setActivity(`plan: ${titles.join(', ')}`)\n        break\n      }\n      case 'plan_complete':\n      case 'plan_complete_summary':\n        this.setPhase('planning')\n        this.setActivity('plan complete, starting execution')\n        break\n      case 'init':\n        this.protocol = numberField(event, 'protocol')\n        this.project = stringField(event, 'project')\n        // Progressive planning inits with an empty graph and fills it by fragments; keep what we counted.\n        this.storiesTotal = (Array.isArray(event.stories) ? event.stories.length : 0) || this.storiesTotal\n        this.setPhase('executing')\n        break\n      case 'activity': {\n        const text = stringField(event, 'text')\n        const id = stringField(event, 'id')\n        if (text) this.setActivity(id && id !== 'plan' ? `${id}: ${text}` : text)\n        break\n      }\n      case 'story_log': {\n        const line = stringField(event, 'line')\n        const id = stringField(event, 'id')\n        if (line) this.setActivity(id && id !== 'plan' ? `${id}: ${line}` : line)\n        break\n      }\n      case 'progress': {\n        const completed = numberField(event, 'completed', 'done')\n        const total = numberField(event, 'total')\n        if (completed !== undefined) this.completed = completed\n        if (total !== undefined) this.total = total\n        break\n      }\n      case 'finalize_start':\n        this.setPhase('finalizing')\n        break\n      case 'push_status':\n      case 'finalize_complete': {\n        const url = stringField(event, 'pr_url', 'url')\n        if (url) this.prUrl = url\n        break\n      }\n      case 'done':\n        this.done = event\n        this.setPhase('done')\n        break\n    }\n    if (isMilestone(event)) {\n      this.milestones.push(describe(event))\n      if (this.milestones.length > this.limit) this.milestones.shift()\n      this.revision += 1\n    } else if (this.revision === before && (event.type === 'progress' || event.type === 'push_status')) {\n      this.revision += 1\n    }\n  }\n\n  summary(): RunSummary {\n    return {\n      protocol: this.protocol,\n      project: this.project,\n      phase: this.phase,\n      activity: this.activity,\n      storiesTotal: this.storiesTotal,\n      completed: this.completed,\n      total: this.total,\n      prUrl: this.prUrl,\n      done: this.done,\n      milestones: [...this.milestones],\n      revision: this.revision,\n    }\n  }\n\n  private setPhase(phase: Phase): void {\n    if (this.phase === phase) return\n    this.phase = phase\n    this.revision += 1\n  }\n\n  private setActivity(text: string): void {\n    const next = text.length > ACTIVITY_LIMIT ? `${text.slice(0, ACTIVITY_LIMIT - 1)}…` : text\n    if (this.activity === next) return\n    this.activity = next\n    this.revision += 1\n  }\n}\n\n/** The snapshot a panel reads: headline facts, then the milestone log. */\nexport function renderProgress(summary: RunSummary): string {\n  const head = [\n    `phase: ${summary.phase}`,\n    summary.activity ? `activity: ${summary.activity}` : undefined,\n    summary.project ? `project: ${summary.project}` : undefined,\n    summary.total > 0\n      ? `progress: ${summary.completed}/${summary.total}`\n      : summary.storiesTotal\n        ? `stories: ${summary.storiesTotal}`\n        : undefined,\n    summary.prUrl ? `pr: ${summary.prUrl}` : undefined,\n  ].filter((line): line is string => line !== undefined)\n  return [...head, ...(head.length ? [''] : []), ...summary.milestones].join('\\n')\n}\n\n/** The prose a delegating agent receives back. */\nexport function renderOutcome(summary: RunSummary, terminal: Terminal): string {\n  const done = summary.done\n  const lines: string[] = []\n  if (done) {\n    const code = stringField(done, 'abort_code')\n    const reason = stringField(done, 'abort_reason')\n    const stats = done.stats as Record<string, unknown> | undefined\n    if (done.success === true) {\n      lines.push('baro run succeeded.')\n    } else if (deliveredDespiteContract(done)) {\n      lines.push('baro run delivered: every story merged and verification passed, but baro left its goal contract open.')\n      if (reason) lines.push(`open contract: ${reason}`)\n    } else {\n      lines.push(`baro run failed${code ? ` (${code})` : ''}.`)\n      if (reason) lines.push(reason)\n    }\n    if (stats) {\n      const facts = [\n        `stories completed: ${String(stats.stories_completed ?? '?')}, skipped: ${String(stats.stories_skipped ?? '?')}`,\n        typeof stats.total_commits === 'number' ? `commits: ${stats.total_commits}` : undefined,\n        typeof stats.files_created === 'number' || typeof stats.files_modified === 'number'\n          ? `files created: ${String(stats.files_created ?? 0)}, modified: ${String(stats.files_modified ?? 0)}`\n          : undefined,\n      ].filter((f): f is string => f !== undefined)\n      lines.push(...facts)\n    }\n    const verification = stringField(done, 'verification_status')\n    if (verification) lines.push(`verification: ${verification}`)\n    if (done.success !== true) lines.push('Changes are committed in the working directory; inspect them with git log.')\n  } else {\n    lines.push(`baro run ended without a result (${terminal}).`)\n  }\n  if (summary.prUrl) lines.push(`pull request: ${summary.prUrl}`)\n  const tail = summary.milestones.slice(-12)\n  if (tail.length) lines.push('', 'milestones:', ...tail)\n  return lines.join('\\n')\n}\n"
    },
    {
      "path": "packages/baro-dsh/src/adapters/dsh/settings-observer.ts",
      "content": "import type { RunObserverPort, RunSubscription, RunView } from '../../application/delegate-run.js'\nimport type { Phase, Terminal } from '../../domain/run.js'\n\n/* The host→browser channel an out-of-tree plugin has: a settings namespace.\n   dsh forwards `settings/document-updated` to every client, and the settings\n   remote serves the namespace value, so a panel can follow a run without a\n   remote of our own (the remote assembly is fixed at dsh build time). Writes\n   are throttled — every update persists to settings.yaml. */\n\nexport type RunStatus = 'running' | Terminal\n\nexport interface RunRecord {\n  readonly label: string\n  readonly status: RunStatus\n  readonly startedAt: string\n  readonly finishedAt: string | null\n  readonly project: string | null\n  readonly phase: Phase\n  readonly activity: string | null\n  readonly completed: number\n  readonly total: number\n  readonly prUrl: string | null\n  /** Newest last. */\n  readonly milestones: readonly string[]\n}\n\nexport interface RunsDocument {\n  readonly runs: Readonly<Record<string, RunRecord>>\n}\n\nexport interface RunsSink {\n  get(): RunsDocument\n  update(patch: { runs: Record<string, RunRecord> }): Promise<void>\n}\n\nexport interface SettingsObserverOptions {\n  /** Minimum gap between two persisted updates of one run. */\n  readonly throttleMs?: number\n  /** Finished runs kept in the document, oldest dropped first. */\n  readonly keepFinished?: number\n  /** Milestone lines kept per run. */\n  readonly tail?: number\n  readonly now?: () => number\n  readonly setTimeout?: (fn: () => void, ms: number) => unknown\n}\n\nexport class SettingsObserver implements RunObserverPort {\n  private readonly throttleMs: number\n  private readonly keepFinished: number\n  private readonly tail: number\n  private readonly now: () => number\n  private readonly schedule: (fn: () => void, ms: number) => unknown\n  private chain: Promise<void> = Promise.resolve()\n\n  constructor(\n    private readonly sink: RunsSink,\n    private readonly onError: (error: unknown) => void,\n    options: SettingsObserverOptions = {},\n  ) {\n    this.throttleMs = options.throttleMs ?? 1_000\n    this.keepFinished = options.keepFinished ?? 5\n    this.tail = options.tail ?? 8\n    this.now = options.now ?? Date.now\n    this.schedule = options.setTimeout ?? ((fn, ms) => setTimeout(fn, ms))\n  }\n\n  opened(view: RunView): RunSubscription {\n    let lastWrite = 0\n    let pending = false\n    let finished: Terminal | undefined\n\n    const record = (): RunRecord => {\n      const s = view.summary()\n      return {\n        label: view.label,\n        status: finished ?? 'running',\n        startedAt: view.startedAt,\n        finishedAt: finished ? new Date(this.now()).toISOString() : null,\n        project: s.project ?? null,\n        phase: s.phase,\n        activity: s.activity ?? null,\n        completed: s.completed,\n        total: s.total || s.storiesTotal,\n        prUrl: s.prUrl ?? null,\n        milestones: s.milestones.slice(-this.tail),\n      }\n    }\n    const write = () => {\n      pending = false\n      lastWrite = this.now()\n      this.persist(view.id, record())\n    }\n    const request = () => {\n      if (pending) return\n      const wait = this.throttleMs - (this.now() - lastWrite)\n      if (wait <= 0) {\n        write()\n        return\n      }\n      pending = true\n      this.schedule(write, wait)\n    }\n\n    write()\n    return {\n      changed: request,\n      closed: terminal => {\n        finished = terminal\n        pending = false\n        write()\n      },\n    }\n  }\n\n  /** Serialized read-modify-write: two runs updating at once must not lose each other. */\n  private persist(id: string, next: RunRecord): void {\n    this.chain = this.chain\n      .then(async () => {\n        const current = this.sink.get().runs\n        const runs: Record<string, RunRecord> = { ...current, [id]: next }\n        prune(runs, this.keepFinished)\n        await this.sink.update({ runs })\n      })\n      .catch(this.onError)\n  }\n}\n\nfunction prune(runs: Record<string, RunRecord>, keepFinished: number): void {\n  const finished = Object.entries(runs)\n    .filter(([, r]) => r.status !== 'running')\n    .sort(([, a], [, b]) => (a.finishedAt ?? '').localeCompare(b.finishedAt ?? ''))\n  for (const [id] of finished.slice(0, Math.max(0, finished.length - keepFinished))) delete runs[id]\n}\n"
    },
    {
      "path": "packages/baro-dsh/src/client/index.tsx",
      "content": "import type { Context as ClientContext } from '@deepseek-ai/cordis'\nimport type {} from '@deepseek-ai/dsh-client-locale/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-renderer/client'\nimport type {} from '@deepseek-ai/dsh-client-ui-sidebar/client'\nimport type {} from '@deepseek-ai/dsh-api-remotes/client'\nimport type { RunsDocument } from '../adapters/dsh/settings-observer.js'\nimport { BaroPanel } from './BaroPanel.js'\nimport { en, NS, zh, type BaroKey } from './locales.js'\nimport { RunsStore } from './store.js'\n\n/* Browser half of the plugin. Reads run state the host wrote into the\n   `baro-dsh` settings namespace, refreshes on the forwarded update event,\n   and renders a footer action in the sidebar. Value imports stay inside dsh's\n   browser baseline (React, Cordis); everything from dsh is type-only. */\n\ndeclare module '@deepseek-ai/dsh-client-ui-slots' {\n  interface LocaleNamespaceMap {\n    baro: BaroKey\n  }\n}\n\nconst RUNS_SETTINGS_NS = 'baro-dsh'\n\n// `remote.settings` is a scoped service of its own in cordis, not a property of `remote`.\nexport const inject = ['slots', 'locale', 'remote', 'remote.settings']\n\nexport function apply(ctx: ClientContext): void {\n  ctx.effect(() => ctx.locale.register(NS, { zh, en }), 'baro-dsh: dictionaries')\n\n  const store = new RunsStore(async (): Promise<RunsDocument | null> => {\n    const answered = await ctx.remote.settings.describe()\n    if (!answered.ok) throw new Error(`${answered.error.code}: ${answered.error.message}`)\n    const view = answered.value.namespaces.find((entry: { ns: string; value: unknown }) => entry.ns === RUNS_SETTINGS_NS)\n    return view ? (view.value as unknown as RunsDocument) : null\n  })\n\n  ctx.effect(() => {\n    const disposers = [\n      ctx.remote.$on('settings/document-updated', (ns: string) => {\n        if (ns === RUNS_SETTINGS_NS) void store.refresh()\n      }),\n      ctx.on('connection/reset', () => {\n        store.reset()\n        void store.refresh()\n      }),\n    ]\n    // Belt and braces for the event: while a run is live, poll slowly too. The\n    // document is small and the host writes at most once a second anyway.\n    const poll = setInterval(() => {\n      if (store.getSnapshot().running > 0) void store.refresh()\n    }, 4_000)\n    void store.refresh()\n    return () => {\n      clearInterval(poll)\n      for (const dispose of disposers) dispose()\n    }\n  }, 'baro-dsh: run state')\n\n  ctx.slots.inject('sidebar.footer.action', () =>\n    ctx.slots.register(\n      {\n        name: 'sidebar.footer.action',\n        id: 'baro-panel',\n        locale: NS,\n        inject: () => ({ store }),\n      },\n      BaroPanel as never,\n    ),\n  )\n}\n"
    }
